<?php namespace App\Http\Controllers; use App\Http\Requests\CareContentRequest; use App\Models\CareContent; use Illuminate\Http\Request; class CareContentController extends Controller { public function index(Request $r){return CareContent::where('is_published',true)->when($r->category,fn($q,$c)=>$q->where('category',$c))->when($r->type,fn($q,$t)=>$q->where('type',$t))->latest()->paginate(20);} public function store(CareContentRequest $r){return CareContent::create($r->validated());} public function update(CareContentRequest $r,CareContent $careContent){$careContent->update($r->validated());return $careContent;} public function destroy(CareContent $careContent){$careContent->delete();return response()->noContent();} }